contract InvMutTest {
    C c;
    bool refuseEther;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint a, uint b) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a) + (b)); require(a <= 1000000000000000000000000000000); require(b <= 1000000000000000000000000000000);
        require(a > 0);
        require(b > 0);
        require(address(this).balance >= a + b);

        // Deposit a; withdrawing with a reverting receiver must fail and keep credit.
        c.deposit{value: a}(); if (__ESBMC_reverted()) return;
        refuseEther = true;
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }

        // Recover: deposit b more, then withdraw all with an accepting receiver.
        refuseEther = false;
        c.deposit{value: b}(); if (__ESBMC_reverted()) return;
        uint before = address(this).balance;
        uint cBefore = address(c).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;

        assert(firstReverted && address(this).balance == before + a + b && address(c).balance == cBefore - a - b);
    }

    receive() external payable {
        require(!refuseEther);
    }
}

