// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;
    bool refuseEther;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 a, uint256 b) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        b = bound(b, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a > 0);
        vm.assume(b > 0);
        vm.assume(address(this).balance >= a + b);
        try c.deposit{value: a}() {} catch { return; }
        refuseEther = true;
        bool firstReverted;
        try c.withdrawAll() { firstReverted = false; } catch { firstReverted = true; }
        refuseEther = false;
        try c.deposit{value: b}() {} catch { return; }
        uint before = address(this).balance;
        uint cBefore = address(c).balance;
        try c.withdrawAll() {} catch { return; }
        assertTrue(firstReverted && address(this).balance == before + a + b && address(c).balance == cBefore - a - b);
    }

    function testFuzz_run(uint256 a, uint256 b) public {
        _run(a, b);
    }

    receive() external payable {
        require(!refuseEther);
    }
}
